import{_ as e,o as t,c as i,a6 as l}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"关于本课程","description":"","frontmatter":{"title":"关于本课程"},"headers":[],"relativePath":"immersive-translate-course/about.md","filePath":"immersive-translate-course/docs/about.md"}'),r={name:"immersive-translate-course/about.md"};function o(s,a,n,c,h,d){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="关于本课程" tabindex="-1">关于本课程 <a class="header-anchor" href="#关于本课程" aria-label="Permalink to &quot;关于本课程&quot;">​</a></h1><p><strong>原文纹丝不动的页面上，译文是怎么逐段长出来的——还跟得上无限滚动？</strong></p><p>全书九章就是这句话的答案：第 2~3 章回答「逐段长出来」（可译块抽取 + 兄弟节点渲染），第 4~7 章回答「译文从哪来、怎么省钱」（服务抽象 + 格式保留 + 正文识别 + 批量缓存），第 8 章回答「跟得上无限滚动」（MutationObserver 增量），第 9 章把它装进真实浏览器亲眼验证。</p><h2 id="课程由来" tabindex="-1">课程由来 <a class="header-anchor" href="#课程由来" aria-label="Permalink to &quot;课程由来&quot;">​</a></h2><p>输入是一个主题句：「沉浸式翻译原理复刻：把双语对照翻译工具的核心引擎拆开教、动手重做」。全书按「先验证物后文」生成：每章先在伴生验证工程（companion/）里把测试写红、实现转绿，再基于真实产物写正文——正文里的每个数字、每段代码，都以验证工程的机械输出为事实源。</p><ul><li>章节数：9 章（完成 9/9），3 个分部</li><li>验证物工程：TypeScript + vitest + jsdom，8 个测试文件 / 74 项测试全绿，7 个可跑 demo，1 个可装进 Chrome 的扩展壳</li><li>读者画像：会写 TS 与原生 DOM、想复刻双语翻译工具的开发者</li></ul><h2 id="能力阶梯" tabindex="-1">能力阶梯 <a class="header-anchor" href="#能力阶梯" aria-label="Permalink to &quot;能力阶梯&quot;">​</a></h2><ul><li>学完第 1 章（整页替换 vs 双语对照：两种翻译世界观）：建立全书世界观：翻译网页不是字符串替换，而是在活的对象树上做增量；拆出引擎的四个部件</li><li>学完第 2 章（可译块：找到直接持有文字的节点）：实现可译块抽取：递归遍历 DOM、按块级/内联分类、只取直接持有文本的块、套用跳过规则</li><li>学完第 3 章（双语渲染：原文纹丝不动，译文插到下面）：实现双语渲染：在可译块后插入带标记的译文节点，不改原文一个字；幂等，重复调用不产生重复译文</li><li>学完第 4 章（翻译服务抽象：引擎不认识任何 API）：定义 Translator 接口与确定性假翻译器，组装「抽取→翻译→渲染」最小管线：一次调用整页变双语，且全程离线可测</li><li>学完第 5 章（内联格式保留：译文里的加粗和链接）：解决「翻译往返碾平格式」：让译文里的 strong/a/code 结构与原文一一对应（内联切分与占位标记两方案的取舍在…</li><li>学完第 6 章（主内容识别：别把额度花在导航栏上）：实现主内容区启发式：用文字密度/链接密度给候选容器打分，从全页可译块里筛出正文，跳过导航、侧栏、页脚</li><li>学完第 7 章（批量、去重与缓存：翻译的经济学）：实现按字符预算分块、并发上限队列、内容寻址缓存：同样的话只翻一次、同时在飞的请求有上限、二次渲染零请求</li><li>学完第 8 章（动态内容：别让译文生译文）：用 MutationObserver 适配动态页面：懒加载内容增量翻译；标记过滤防自触发循环；断开重连语义</li><li>学完第 9 章（装进浏览器：从 jsdom 到真实页面）：给引擎一个身体：manifest + content script 最小扩展壳，开发者模式加载，离线假翻译器在真实页面…</li></ul><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><ul><li><a href="./glossary.html">术语表</a>——全书 29 个概念的一句话定义</li><li><a href="./node-cheatsheet.html">节点分类速查表</a>——块级清单、跳过清单与长度门槛，与 companion/src/extract.ts 逐字一致</li><li><a href="./divergence.html">与真实产品的差异清单</a>——全书每一处「本课程简化为…」的集中登记，也是接真实服务的路线图</li></ul>',10)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
